class BrokenCounter {
    private int count = 0;

    // WRONG: checking and waiting are not atomic
    public void waitForNonZero() throws InterruptedException {
        if (count == 0) {
            // Another thread could increment and notify HERE
            // Then this wait() would miss that notification
            wait();  // Also throws IllegalMonitorStateException!
        }
    }

    // CORRECT: synchronized makes check and wait atomic
    public synchronized void waitForNonZeroCorrect() throws InterruptedException {
        while (count == 0) {
            wait();  // atomically releases monitor and waits
        }
        // When we wake up, we still hold the lock
        System.out.println("Count is now: " + count);
    }

    public synchronized void increment() {
        count++;
        notifyAll();  // must hold monitor to notify
    }
}
