class MultiResourceService {
    private final Object customerLock = new Object();
    private final Object orderLock = new Object();
    private boolean customersReady = false;
    private boolean ordersReady = false;

    public void waitForCustomers() throws InterruptedException {
        synchronized (customerLock) {  // customerLock is the monitor
            while (!customersReady) {
                customerLock.wait();  // wait on customerLock's waiting set
            }
        }
    }

    public void waitForOrders() throws InterruptedException {
        synchronized (orderLock) {  // orderLock is a different monitor
            while (!ordersReady) {
                orderLock.wait();  // wait on orderLock's waiting set
            }
        }
        // These two waiting sets are completely independent
    }

    public void markCustomersReady() {
        synchronized (customerLock) {
            customersReady = true;
            customerLock.notifyAll();  // wakes only customerLock waiters
        }
    }
}
