import java.util.LinkedList;
import java.util.Queue;

class SafeQueue<T> {
    private final Queue<T> items = new LinkedList<>();
    private final int capacity;

    public SafeQueue(int capacity) {
        this.capacity = capacity;
    }

    public synchronized void put(T item) throws InterruptedException {
        while (items.size() >= capacity) {  // WHILE not IF
            wait();  // may wake spuriously
        }
        // When we reach here, we KNOW size < capacity
        items.add(item);
        notifyAll();
    }

    public synchronized T take() throws InterruptedException {
        while (items.isEmpty()) {  // WHILE not IF
            wait();  // may wake spuriously or due to another take()
        }
        // When we reach here, we KNOW the queue is non-empty
        var item = items.poll();
        notifyAll();
        return item;
    }
}
```
